// #c937f5ca1b172513b5ce1e2d — сообщение «הגרסה הקודמת נשמרה» только когда предыдущая версия есть.
// ВНИМАНИЕ: конфигурации провайдеров неудаляемы. Каждый прогон берёт НОВЫЙ тестовый код языка
// из зарезервированного диапазона ISO 639 «qaa–qtz» (q + 2 буквы), которого ещё нет в конфигурациях.
// Рабочий иврит (he) и любые существующие языки не трогаются никогда (защита ниже).
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';
import { openWithApi, runStamp } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });
test.describe.configure({ mode: 'serial' });

const FORBIDDEN_LANGS = ['he', 'en', 'ar', 'ru'];
let lang = '';
const stamp = runStamp();

async function pickUnusedLang(page: Page): Promise<string> {
  const api = await openWithApi(page, '/admin/providers');
  const res = await api.rpc('admin_list_provider_configs');
  expect(res.status()).toBe(200);
  const used = new Set(((await res.json()) as { language: string }[]).map((r) => r.language.trim().toLowerCase()));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  for (let i = 0; i < 200; i++) {
    const code = 'q' + letters[Math.floor(Math.random() * 20)] /* a–t */ + letters[Math.floor(Math.random() * 26)];
    if (!used.has(code) && !FORBIDDEN_LANGS.includes(code)) return code;
  }
  throw new Error('Не нашлось свободного тестового кода языка q??');
}

async function fillAndSave(page: Page, settings: string) {
  expect(FORBIDDEN_LANGS, 'тест не должен сохранять конфигурацию рабочего языка').not.toContain(lang);
  const form = page.getByRole('region', { name: 'הגדרת ספק' });
  const capability = form.getByRole('combobox', { name: 'יכולת' });
  // В режиме правки יכולת заблокирована (уже выбрана правкой строки).
  if (await capability.isEnabled()) await capability.selectOption({ label: 'תמלול' });
  else await expect(capability).toHaveValue('transcription');
  await form.getByRole('textbox', { name: 'שפה' }).fill(lang);
  await expect(form.getByRole('textbox', { name: 'שפה' })).toHaveValue(lang);
  await form.getByRole('textbox', { name: 'מזהה הספק (חובה)' }).fill('soniox');
  await form.getByRole('textbox', { name: 'מזהה המודל (חובה)' }).fill('stt-async-v5');
  await form.getByRole('textbox', { name: 'הגדרות נוספות (לא חובה)' }).fill(settings);
  const saved = page.waitForResponse((r) => r.url().includes('/rpc/admin_set_provider_config'));
  await form.getByRole('button', { name: 'שמירת גרסה חדשה' }).click();
  expect((await saved).status()).toBe(200);
}

test.describe('AI-провайдеры — версии конфигурации (#c937f5ca1b172513b5ce1e2d)', () => {
  test('первая конфигурация для языка без конфигураций — без «הגרסה הקודמת נשמרה» @desktop @data #c937f5ca1b172513b5ce1e2d', async ({ page }) => {
    lang = await pickUnusedLang(page);
    test.info().annotations.push({ type: 'test-data', description: `provider config transcription/${lang} (QA-AUTO-${stamp}), неудаляемо` });

    await fillAndSave(page, JSON.stringify({ qa: `QA-AUTO-${stamp}-v1` }));

    // Источник: «מה רצוי» — «ההודעה מוצגת רק כשקיימת גרסה קודמת».
    await expect(page.getByText('נשמרה גרסה חדשה', { exact: true })).toBeVisible();
    const msg = page.getByText(`תמלול ב${lang}: soniox · stt-async-v5.`);
    await expect(msg).toBeVisible();
    await expect(msg).not.toContainText('הגרסה הקודמת נשמרה');

    const history = page.getByRole('region', { name: 'היסטוריית גרסאות' }).getByRole('row').filter({ hasText: `תמלול · ${lang}` });
    await expect(history).toHaveCount(1);
    await expect(history).toContainText('פעילה');
  });

  test('повторное сохранение той же יכולת+שפה — с «הגרסה הקודמת נשמרה», в истории פעילה + הוחלפה @desktop @data #c937f5ca1b172513b5ce1e2d', async ({ page }) => {
    expect(lang, 'нужен язык из предыдущего теста (serial)').toMatch(/^q[a-z]{2}$/);
    await page.goto('/admin/providers');
    await page.getByRole('button', { name: `עריכה של תמלול ב${lang}` }).click();
    await expect(page.getByRole('region', { name: 'הגדרת ספק' }).getByRole('combobox', { name: 'יכולת' })).toBeDisabled();

    await fillAndSave(page, JSON.stringify({ qa: `QA-AUTO-${stamp}-v2` }));

    await expect(page.getByText('נשמרה גרסה חדשה', { exact: true })).toBeVisible();
    await expect(page.getByText(`תמלול ב${lang}: soniox · stt-async-v5. הגרסה הקודמת נשמרה בהיסטוריה.`)).toBeVisible();

    const history = page.getByRole('region', { name: 'היסטוריית גרסאות' }).getByRole('row').filter({ hasText: `תמלול · ${lang}` });
    await expect(history).toHaveCount(2);
    await expect(history.filter({ hasText: 'פעילה' })).toHaveCount(1);
    await expect(history.filter({ hasText: 'הוחלפה' })).toHaveCount(1);
    await expect(history.first()).toContainText('admin@admin.com');
  });
});
